    #include <iostream>
using namespace std;

int gcd(int a, int b)
{
    // Everything divides 0
    if (a == 0)
        return b;
    if (b == 0)
        return a;

    // Base case
    if (a == b)
        return a;

    // a is greater
    if (a > b)
    {
        if (a % b == 0)
            return b;
        return gcd(a - b, b);
    }

    // b is greater
    if (b % a == 0)
        return a;
    return gcd(a, b - a);
}

